cssCode:
.vinyl-player {
  width: 150px; height: 150px;
  background: #111;
  border-radius: 50%;
  position: relative;
  border: 4px solid #333;
  box-shadow: 0 10px 30px rgba(0,0,0,0.8), inset 0 0 10px #000;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  animation: spinRecord 4s linear infinite;
  animation-play-state: paused;
}
.vinyl-player.playing { animation-play-state: running; }
.vinyl-center {
  width: 50px; height: 50px;
  background: linear-gradient(45deg, #ff007f, #7928ca);
  border-radius: 50%; position: relative;
}
.vinyl-center::after {
  content: ''; position: absolute; top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  width: 10px; height: 10px; background: #fff; border-radius: 50%;
}
@keyframes spinRecord { 100% { transform: rotate(360deg); } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const player = document.createElement('div');
player.className = 'vinyl-player';

const center = document.createElement('div');
center.className = 'vinyl-center';

player.appendChild(center);
c.appendChild(player);

player.addEventListener('click', () => {
  player.classList.toggle('playing');
});
